import React, { useEffect, useMemo, useState } from 'react';
import { useSelector } from 'react-redux';
import { FaAngleLeft, FaAngleRight, FaPlay } from 'react-icons/fa6';
import { Link } from 'react-router-dom';
import moment from 'moment';
import Button from '../../../components/ui/Button';
import Badge from '../../../components/ui/Badge';
import RatingBadge from '../../../components/ui/RatingBadge';
import IconButton from '../../../components/ui/IconButton';
import GenreChip from '../../../components/ui/GenreChip';
import VideoPlay from '../../../components/media/VideoPlay';
import useFetchDetails from '../../../hooks/useFetchDetails';

const BannerHome = () => {
  const bannerData = useSelector((state) => state.movieData.bannerData);
  const imageURL = useSelector((state) => state.movieData.imageURL);
  const [currentImage, setCurrentImage] = useState(0);
  const [playVideo, setPlayVideo] = useState(false);

  const currentData = bannerData[currentImage];
  const mediaType = currentData?.media_type || 'movie';
  const detailsEndpoint = currentData?.id ? `/${mediaType}/${currentData.id}` : '';
  const { data: detailsData } = useFetchDetails(detailsEndpoint);

  const runtime = useMemo(() => {
    const minutes = Number(detailsData?.runtime || detailsData?.episode_run_time?.[0] || 0);
    if (!minutes) return null;
    const hours = Math.floor(minutes / 60);
    const remainder = minutes % 60;
    return `${hours ? `${hours}h ` : ''}${remainder}m`;
  }, [detailsData]);

  const handleNext = () => {
    setPlayVideo(false);
    setCurrentImage((previous) =>
      previous < bannerData.length - 1 ? previous + 1 : 0
    );
  };

  const handlePrevious = () => {
    setPlayVideo(false);
    setCurrentImage((previous) =>
      previous > 0 ? previous - 1 : Math.max(bannerData.length - 1, 0)
    );
  };

  useEffect(() => {
    if (bannerData.length <= 1 || playVideo) return undefined;

    const interval = setInterval(() => {
      setCurrentImage((previous) =>
        previous < bannerData.length - 1 ? previous + 1 : 0
      );
    }, 7000);

    return () => clearInterval(interval);
  }, [bannerData.length, playVideo]);

  if (!bannerData.length) {
    return <div className='h-[68vh] min-h-[500px] w-full animate-pulse bg-neutral-900' />;
  }

  return (
    <section className='relative w-full overflow-hidden'>
      <div className='flex h-[78vh] min-h-[540px] max-h-[860px]'>
        {bannerData.map((data, index) => (
          <article
            key={`${data.id}-banner-${index}`}
            className='relative min-h-full min-w-full overflow-hidden transition-transform duration-700 ease-out'
            style={{ transform: `translateX(-${currentImage * 100}%)` }}
            aria-hidden={index !== currentImage}
          >
            {data.backdrop_path ? (
              <img
                src={`${imageURL}${data.backdrop_path}`}
                alt={data?.title || data?.name || 'Featured title'}
                className='h-full w-full object-cover object-center'
              />
            ) : null}
            <div className='absolute inset-0 bg-gradient-to-r from-neutral-950 via-neutral-950/70 to-neutral-950/5' />
            <div className='absolute inset-0 bg-gradient-to-t from-neutral-950 via-transparent to-black/30' />

            <div className='absolute inset-0 flex items-end'>
              <div className='mx-auto w-full max-w-[1600px] px-4 pb-14 sm:px-6 lg:px-10 lg:pb-20'>
                <div className='max-w-3xl'>
                  <div className='mb-3 flex flex-wrap items-center gap-2'>
                    <Badge>{data.media_type === 'tv' ? 'TV Series' : 'Movie'}</Badge>
                    <RatingBadge value={data.vote_average} />
                    {(data.release_date || data.first_air_date) ? (
                      <span className='text-sm font-semibold text-neutral-300'>
                        {moment(data.release_date || data.first_air_date).format('YYYY')}
                      </span>
                    ) : null}
                    {index === currentImage && runtime ? (
                      <span className='text-sm font-semibold text-neutral-300'>{runtime}</span>
                    ) : null}
                  </div>

                  <h1 className='max-w-3xl text-4xl font-black tracking-tight text-white drop-shadow-2xl sm:text-5xl lg:text-7xl'>
                    {data?.title || data?.name}
                  </h1>

                  {index === currentImage && detailsData?.genres?.length ? (
                    <div className='mt-4 flex flex-wrap gap-2'>
                      {detailsData.genres.slice(0, 4).map((genre) => (
                        <GenreChip key={genre.id}>{genre.name}</GenreChip>
                      ))}
                    </div>
                  ) : null}

                  <p className='mt-4 line-clamp-3 max-w-2xl text-sm leading-6 text-neutral-200 sm:text-base lg:text-lg lg:leading-7'>
                    {data.overview || 'Discover this featured title on CineVerse.'}
                  </p>

                  <div className='mt-6 flex flex-wrap gap-3'>
                    <Button onClick={() => setPlayVideo(true)} className='px-5 py-2.5'>
                      <FaPlay className='text-sm' /> Watch Trailer
                    </Button>
                    <Link to={`/${data.media_type}/${data.id}`}>
                      <Button variant='secondary' className='px-5 py-2.5'>View Details</Button>
                    </Link>
                  </div>
                </div>
              </div>
            </div>
          </article>
        ))}
      </div>

      <div className='pointer-events-none absolute inset-y-0 left-0 right-0 hidden items-center justify-between px-4 sm:flex lg:px-8'>
        <IconButton
          onClick={handlePrevious}
          variant='glass'
          className='pointer-events-auto'
          aria-label='Previous featured title'
        >
          <FaAngleLeft />
        </IconButton>
        <IconButton
          onClick={handleNext}
          variant='glass'
          className='pointer-events-auto'
          aria-label='Next featured title'
        >
          <FaAngleRight />
        </IconButton>
      </div>

      <div className='absolute bottom-5 left-1/2 flex -translate-x-1/2 gap-1.5 sm:hidden'>
        {bannerData.slice(0, 8).map((item, index) => (
          <button
            key={`${item.id}-hero-dot`}
            type='button'
            onClick={() => setCurrentImage(index)}
            className={`h-1.5 rounded-full transition-all ${
              currentImage === index ? 'w-6 bg-white' : 'w-1.5 bg-white/40'
            }`}
            aria-label={`Show featured title ${index + 1}`}
          />
        ))}
      </div>

      {playVideo && currentData ? (
        <VideoPlay
          data={currentData}
          close={() => setPlayVideo(false)}
          media_type={mediaType}
        />
      ) : null}
    </section>
  );
};

export default BannerHome;
